model:
rachana: 1
sutra: development-profile
version: 1
description: 
match: { kind: development-profile, priority: 10 }
title: { pill: "Public sector · Development profile", id: "$.PROFILE_ID", with: "$.COUNTRY_NAME" }
strip:
  - { label: "Country", bind: "$.COUNTRY_NAME", emphasis: true }
  - { label: "Region", bind: "$.REGION" }
  - { label: "Income group", bind: "$.INCOME_GROUP" }
  - { label: "Capital", bind: "$.CAPITAL" }
  - { label: "Population", bind: "$.POPULATION", fmt: "compact" }
  - { label: "GDP per head, USD", bind: "$.GDP_PER_CAPITA", fmt: "amount0" }
panels:
  - id: indicators
    kind: table
    title: "Indicators, latest year (a row opens its series)"
    key: "F2"
    code: "IND"
    rows: "$.INDICATORS"
    search: false
    columns:
      - { label: "Indicator", bind: "link(@.WDI_SERIES, 'development-series', @.INDICATOR)" }
      - { label: "Latest", bind: "@.LATEST", fmt: "amount2" }
      - { label: "Unit", bind: "@.UNIT" }
      - { label: "Year", bind: "@.YEAR" }
  - id: world
    kind: map
    title: "GDP per head by country, USD (a country opens its profile)"
    key: "F3"
    height: 11
    phone: { tier: "glance", from: "fragment", rows: 5 }
    highlight: "$.ISO3"
    link: { kind: "development-profile", id: "WDI-{iso3}" }
    shade: { kind: "development-profile", field: "$.GDP_PER_CAPITA", by: "$.ISO3", fmt: "amount0", label: "GDP per head, USD" }
  - id: source
    kind: kv
    title: "Data source and licence"
    area: right
    phone: { tier: "must", from: "fragment" }
    rows: "$.PROVENANCE"
  - id: built
    kind: provenance
    title: "How this view was built"
    phone: { tier: "more", from: "fragment" }
  - id: refs
    kind: links
    title: "Linked entities"
    code: "REFS"
    area: right
    phone: { tier: "more", from: "fragment" }
keys: { F9: "raw" }
